import random, hashlib, json

# --- Minimal ClayCode function-definition closure test ---
# Tests: parse needle-with-body, canonical IR, typecheck, call resolution

def parse_needle_decl(line):
    # needle NAME(params) -> TypeExpr = body_expr
    assert line.startswith('needle ')
    rest = line[len('needle '):]
    name_end = rest.index('(')
    name = rest[:name_end_end] if False else rest[:name_end]
    rest = rest[name_end+1:]
    params_end = rest.index(')')
    params_str = rest[:params_end]
    rest = rest[params_end+1:]
    assert rest.startswith(' -> ')
    rest = rest[4:]
    # split return type and body
    if ' = ' in rest:
        ret_type, body = rest.split(' = ', 1)
    else:
        ret_type, body = rest, None
    params = []
    if params_str.strip():
        for p in params_str.split(','):
            pname, ptype = p.split(':')
            params.append((pname.strip(), ptype.strip()))
    return {'name': name.strip(), 'params': params, 'ret_type': ret_type.strip(), 'body': body}

def typecheck_call(func_defs, call_name, call_args, call_arg_types):
    if call_name not in func_defs:
        return False, f'UNDEFINED_TARGET:{call_name}'
    fd = func_defs[call_name]
    if len(fd['params']) != len(call_arg_types):
        return False, f'ARITY_MISMATCH:{len(fd["params"])}!={len(call_arg_types)}'
    for (pname, ptype), atype in zip(fd['params'], call_arg_types):
        if ptype != atype:
            return False, f'TYPE_MISMATCH:{pname}:{ptype}!={atype}'
    return True, None

def eval_body(body, func_defs, env):
    if body is None:
        return None
    body = body.strip()
    # handle: n==0, is_even(n-1)==false, etc.
    if '==' in body:
        lhs, rhs = body.split('==', 1)
        lhs_v = eval_simple(lhs.strip(), func_defs, env)
        rhs_v = eval_simple(rhs.strip(), func_defs, env)
        return lhs_v == rhs_v
    if body in ('true','false'):
        return body == 'true'
    return eval_simple(body, func_defs, env)

def eval_simple(expr, func_defs, env):
    expr = expr.strip()
    if expr in env:
        return env[expr]
    if expr == 'true': return True
    if expr == 'false': return False
    try: return int(expr)
    except: pass
    # call: name(args)
    if '(' in expr and expr.endswith(')'):
        cname = expr[:expr.index('(')]
        arg_str = expr[expr.index('(')+1:-1]
        args = []
        if arg_str.strip():
            for a in arg_str.split(','):
                args.append(eval_simple(a.strip(), func_defs, env))
        ok, err = typecheck_call(func_defs, cname, args, [type(a).__name__ for a in args])
        if not ok:
            raise RuntimeError(err)
        # eval body
        fd = func_defs[cname]
        local_env = {}
        for (pname, ptype), aval in zip(fd['params'], args):
            local_env[pname] = aval
        return eval_body(fd['body'], func_defs, local_env)
    # arithmetic: n-1
    if '-' in expr:
        parts = expr.split('-')
        return eval_simple(parts[0], func_defs, env) - eval_simple(parts[1], func_defs, env)
    raise ValueError(f'cannot eval: {expr}')

# --- Test program ---
source = '''needle is_even(n:Int) -> Bool = n == 0
needle is_odd(n:Int) -> Bool = is_even(n - 1) == false'''

func_defs = {}
for line in source.strip().split('\n'):
    fd = parse_needle_decl(line.strip())
    func_defs[fd['name']] = fd

# Canonical IR hash
canon = json.dumps(func_defs, sort_keys=True)
canon_hash = hashlib.sha256(canon.encode()).hexdigest()

# --- 20,000 randomized composed calls ---
random.seed(42)
mismatches = 0
fail_closed = 0
for i in range(20000):
    n = random.randint(0, 100)
    # is_even
    ok, err = typecheck_call(func_defs, 'is_even', [n], ['int'])
    if not ok:
        fail_closed += 1
        continue
    result = eval_body(func_defs['is_even']['body'], func_defs, {'n': n})
    expected = (n % 2 == 0)
    if result != expected:
        mismatches += 1
    # is_odd via call to is_even
    ok2, err2 = typecheck_call(func_defs, 'is_odd', [n], ['int'])
    if not ok2:
        fail_closed += 1
        continue
    result2 = eval_body(func_defs['is_odd']['body'], func_defs, {'n': n})
    expected2 = (n % 2 == 1)
    if result2 != expected2:
        mismatches += 1

# --- Negative tests: undefined target, arity mismatch, type mismatch ---
neg_results = {}
for bad_call in [('nonexistent', [1], ['int']), ('is_even', [1,2], ['int','int']), ('is_even', ['x'], ['str'])]:
    ok, err = typecheck_call(func_defs, bad_call[0], bad_call[1], bad_call[2])
    neg_results[f'{bad_call[0]}({bad_call[1]})'] = {'ok': ok, 'err': err}

print(json.dumps({
    'canonical_hash': canon_hash[:16],
    'total_calls': 40000,
    'mismatches': mismatches,
    'fail_closed': fail_closed,
    'negative_tests': neg_results,
    'verdict': 'PASS' if mismatches == 0 and all(not v['ok'] for v in neg_results.values()) else 'FAIL'
}, indent=2))
